fetch.body:
{
 "alert_id": "${__data.fields.Alert_id}",
 "status": "false_positive",
 "analyst": "${analyst}",
 "notes": "${analyst} marked the alert as false positive from Grafana"
}

targets.root_selector:
(
$alerts := $[
  status="open" or 
  status="investigating" or 
  status="escalated"
];

$breaches := $alerts[
  (severity="critical" and $millis() - $toMillis(timestamp) > 900000) or
  (severity="high" and $millis() - $toMillis(timestamp) > 3600000) or
  (severity="medium" and $millis() - $toMillis(timestamp) > 14400000) or
  (severity="low" and $millis() - $toMillis(timestamp) > 86400000)
];

$count($breaches)
)

(
  $critical := $count($[severity="critical" and (status="open" or status="investigating")]);
  $high := $count($[severity="high" and (status="open" or status="investigating")]);
  $medium := $count($[severity="medium" and (status="open" or status="investigating")]);

  {
    "metric": "ThreatScore",
    "value": ($critical*5) + ($high*3) + ($medium*1)
  }
)

(
$actions := data;

$distinct($actions.analyst).(
  $a := $;
  {
    "Analyst": $a,
    "Investigated": $count($actions[analyst=$a and action="investigating"]),
    "Escalated": $count($actions[analyst=$a and action="escalated"]),
    "Closed": $count($actions[analyst=$a and action="closed"]),
    "False Positives": $count($actions[analyst=$a and action="false_positive"]),
    "Resolved": $count($actions[analyst=$a and (action="closed" or action="false_positive")])
  }
)
)
